#!/usr/bin/env python3
"""Verify archived KIM mask bytes and generate synthesizable packed constants."""
import argparse
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HASHES = {
    "002": "79c6dbd54aa3911f53c1068c4310aabceb7a6ce9714d1c402b73af76ea109237",
    "003": "80f5c6393e0bbcfc8a5b68fd73858da34e6d6a415f32d4820f21edb52fecafec",
}


def generate():
    lines = ["// Original MOS KIM-1 firmware; see references/README.md.",
             "// Generated by scripts/make_roms.py; byte zero occupies bits 7:0."]
    for part, expected in HASHES.items():
        content = bytes.fromhex((ROOT / "references" / f"6530-{part}.hex").read_text())
        if len(content) != 1024 or hashlib.sha256(content).hexdigest() != expected:
            raise SystemExit(f"Invalid original ROM: 6530-{part}")
        lines.append(f"localparam logic [8191:0] KIM{part}_ROM = {{")
        for offset in range(1008, -1, -16):
            word = content[offset:offset + 16][::-1].hex()
            lines.append(f"    128'h{word}" + ("," if offset else ""))
        lines.append("};")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = ROOT / "src" / "mos_6530_kim_roms.svh"
    generated = generate()
    if args.check:
        if output.read_text() != generated:
            raise SystemExit("Packed ROM constants differ from verified mask bytes")
        print("KIM-1 ROM hashes and packed constants PASS")
    else:
        output.write_text(generated, newline="\n")
